pub fn idle_wait(next_deadline: u64, now_ms: u64) -> u64 {
    let w = if next_deadline > now_ms { next_deadline - now_ms } else { 0 };
    let w = if w > COMMAND_IDLE_POLL_MS { COMMAND_IDLE_POLL_MS } else { w };
    let w = if w > MOTION_WATCHDOG_POLL_MS { MOTION_WATCHDOG_POLL_MS } else { w };
    if w < 1 { 1 } else { w }
}

