pub fn watchdog_on_command(w: Watchdog, kind: MotionKind, now_ms: u64) -> Watchdog {
    match kind {
        MotionKind::Active => Watchdog { active: true, last_motion_ms: now_ms },
        MotionKind::Stop => Watchdog { active: false, last_motion_ms: w.last_motion_ms },
        MotionKind::Other => w,
    }
}

