def watchdog_on_command
  (w : Watchdog) (kind : MotionKind) (now_ms : Std.U64) : Result Watchdog := do
  match kind with
  | MotionKind.Other => ok w
  | MotionKind.Stop => ok { w with active := false }
  | MotionKind.Active => ok { active := true, last_motion_ms := now_ms }

