pub fn may_acquire(held_last_seen: Option<u64>, now_secs: u64) -> bool {
    match held_last_seen {
        None => true,
        Some(last) => {
            let age = if now_secs > last { now_secs - last } else { 0 };
            age > SESSION_TIMEOUT_SECS
        }
    }
}

