pub async fn try_acquire_session(
    session_id: String,
    timestamp: u64,
    lease_id: u64,
) -> bool {
    let mut store = SESSION_STORE.lock().await;
    if let Some((_, held)) = store.as_ref() {
        if timestamp.saturating_sub(held.last_seen) <= SESSION_TIMEOUT_SECS {
            return false;
        }
    }
    *store = Some((
        session_id,
        SessionState {
            last_seen: timestamp,
            lease_id,
        },
    ));
    true
}

